import Mathlib

open Matrix Finset

variable {N : ℕ}

def IsNegSemidef (M : Matrix (Fin N) (Fin N) ℝ) : Prop :=
  ∀ z : Fin N → ℝ, dotProduct z (M.mulVec z) ≤ 0

import Mathlib

def IsHomogeneous (N : ℕ) (f : (Fin N → ℝ) → ℝ) (r : ℝ) : Prop :=
  ∀ (t : ℝ), t > 0 → ∀ (x : Fin N → ℝ), f (t • x) = t ^ r * f x

import Mathlib

open Set

variable {E : Type*} [AddCommMonoid E] [Module ℝ E]

def IsQuasiconcave (f : E → ℝ) : Prop :=
  ∀ α : ℝ, Convex ℝ {x | α ≤ f x}

import Mathlib

open Matrix

variable {N : ℕ}

def MWG.IsNegSemidef (M : Matrix (Fin N) (Fin N) ℝ) : Prop :=
  ∀ z : Fin N → ℝ, z ⬝ᵥ (M *ᵥ z) ≤ 0

import Mathlib

open scoped BigOperators

noncomputable def MWG.Hyperplane (N : ℕ) (p : EuclideanSpace ℝ (Fin N)) (c : ℝ) : Set (EuclideanSpace ℝ (Fin N)) :=
  {z | @inner ℝ _ _ p z = c}

noncomputable def MWG.HalfSpaceAbove (N : ℕ) (p : EuclideanSpace ℝ (Fin N)) (c : ℝ) : Set (EuclideanSpace ℝ (Fin N)) :=
  {z | @inner ℝ _ _ p z ≥ c}

noncomputable def MWG.HalfSpaceBelow (N : ℕ) (p : EuclideanSpace ℝ (Fin N)) (c : ℝ) : Set (EuclideanSpace ℝ (Fin N)) :=
  {z | @inner ℝ _ _ p z ≤ c}

